    print("pysat is not available")

from pysat.solvers import Glucose3

def solve_knights_tour():
    solver = Glucose3()

    # v[i][c] -> variable index: i * 64 + c + 1
    def var(i, c):
        return i * 64 + c + 1

    # 1. Each step has exactly one cell
    for i in range(64):
        solver.add_clause([var(i, c) for c in range(64)])
        for c1 in range(64):
            for c2 in range(c1 + 1, 64):
                solver.add_clause([-var(i, c1), -var(i, c2)])

    # 2. Each cell is visited exactly once
    for c in range(64):
        solver.add_clause([var(i, c) for i in range(64)])
        for i1 in range(64):
            for i2 in range(i1 + 1, 64):
                solver.add_clause([-var(i1, c), -var(i2, c)])

    # Valid knight moves
    def valid_moves(c):
        r, col = c // 8, c % 8
        moves = []
        for dr, dc in [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]:
            nr, ncol = r + dr, col + dc
            if 0 <= nr < 8 and 0 <= ncol < 8:
                moves.append(nr * 8 + ncol)
        return moves

    # 3. Valid transitions
    for i in range(63):
        for c in range(64):
            moves = valid_moves(c)
            # If at step i we are at cell c, at step i+1 we must be at one of the valid moves
            # v[i][c] => v[i+1][m1] or v[i+1][m2] ...
            clause = [-var(i, c)] + [var(i + 1, m) for m in moves]
            solver.add_clause(clause)

    # 4. Fixed assignments
    fixed = {
        0: 0,
        2: 27,
        3: 21,
        10: 16,
        11: 1,
        19: 24,
        21: 3,
        27: 51,
        38: 38,
        50: 43,
        51: 60,
        59: 53,
        61: 42
    }
    for i, c in fixed.items():
        solver.add_clause([var(i, c)])

    print("Solving...")
    if solver.solve():
        print("SAT")
        model = solver.get_model()
        tour = [0] * 64
        for i in range(64):
            for c in range(64):
                if model[var(i, c) - 1] > 0:
                    tour[i] = c
        print("TOUR:", tour)
    else:
        print("UNSAT")

solve_knights_tour()
